{
  "task_summary": "Predict whether an ACS respondent is employed from personal and household characteristics.",
  "ranking": [
    {
      "rank": 1,
      "feature": "AGEP",
      "rationale": "age strongly captures lifecycle labor-force participation and should generalize across states"
    },
    {
      "rank": 2,
      "feature": "DIS",
      "rationale": "overall disability status is directly related to work capacity and employment probability"
    },
    {
      "rank": 3,
      "feature": "SCHL",
      "rationale": "educational attainment is a broadly transferable predictor of employment"
    },
    {
      "rank": 4,
      "feature": "DREM",
      "rationale": "cognitive difficulty is semantically tied to employment barriers"
    },
    {
      "rank": 5,
      "feature": "MIL",
      "rationale": "military service status can reflect labor-market attachment and transferable work history"
    },
    {
      "rank": 6,
      "feature": "MIG",
      "rationale": "recent mobility can affect job transitions but may vary by local labor markets"
    },
    {
      "rank": 7,
      "feature": "MAR",
      "rationale": "marital status captures household and lifecycle structure related to employment"
    },
    {
      "rank": 8,
      "feature": "DEYE",
      "rationale": "vision difficulty can affect work capacity but is narrower than overall disability"
    },
    {
      "rank": 9,
      "feature": "DEAR",
      "rationale": "hearing difficulty can affect employment but is a narrower impairment signal"
    },
    {
      "rank": 10,
      "feature": "CIT",
      "rationale": "citizenship may affect work authorization and opportunity but risks demographic confounding"
    },
    {
      "rank": 11,
      "feature": "NATIVITY",
      "rationale": "nativity can correlate with labor-market access but is largely demographic"
    },
    {
      "rank": 12,
      "feature": "RELP",
      "rationale": "household relationship is indirectly predictive through age and family structure"
    },
    {
      "rank": 13,
      "feature": "ESP",
      "rationale": "parents' employment status is only indirectly relevant and may reflect household artifacts"
    },
    {
      "rank": 14,
      "feature": "GCL",
      "rationale": "grandparent caregiving status is a narrow household-role signal with limited generality"
    },
    {
      "rank": 15,
      "feature": "SEX",
      "rationale": "sex may correlate with employment but is a demographic shortcut to penalize"
    },
    {
      "rank": 16,
      "feature": "RAC1P",
      "rationale": "race is likely to encode structural and geographic disparities rather than causal employability"
    },
    {
      "rank": 17,
      "feature": "ANC",
      "rationale": "ancestry is highly demographic and geography-linked with brittle state-specific correlations"
    }
  ]
}
